    init() {
        this.canvas = document.getElementById('intro-3d-canvas');
        if (!this.canvas) return;
        
        const container = this.canvas.parentElement;
        const width = container.clientWidth || 800;
        const height = container.clientHeight || 560;
        
        this.scene = new THREE.Scene();
        this.camera = new THREE.PerspectiveCamera(60, width / height, 0.1, 1000);
        this.camera.position.set(0, 0, 18);
        
        this.renderer = new THREE.WebGLRenderer({ canvas: this.canvas, antialias: true, preserveDrawingBuffer: true });
        this.renderer.setSize(width, height);
        this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        
        // Lighting
        const ambLight = new THREE.AmbientLight(0xffffff, 0.85);
        this.scene.add(ambLight);
        
        this.pointLight1 = new THREE.PointLight(this.primaryColor, 4, 60);
        this.pointLight1.position.set(12, 12, 12);
        this.scene.add(this.pointLight1);
        
        this.pointLight2 = new THREE.PointLight(this.secondaryColor, 4, 60);
        this.pointLight2.position.set(-12, -12, 12);
        this.scene.add(this.pointLight2);
        
        this.scene.add(this.textMeshGroup);
        this.scene.add(this.logoMeshGroup);
        this.scene.add(this.shockwaveGroup);
        this.scene.add(this.robotMeshGroup);
        this.scene.add(this.hudGroup);
        this.scene.add(this.weatherGroup);
        this.scene.add(this.customModelGroup);
        this.scene.add(this.robot2MeshGroup);
        this.scene.add(this.podiumGroup);
        this.scene.add(this.spotlightsGroup);
        this.scene.add(this.robot3MeshGroup);
        this.scene.add(this.combatFxGroup);
        this.scene.add(this.titanPrimeMeshGroup);
        this.scene.add(this.cataclysmGroup);
        
        this.buildScene();
        this.setupDOMBindings();
        this.animate();
        
        window.addEventListener('resize', () => this.onResize());
    }
    
    onResize() {
        if (!this.canvas || !this.renderer || !this.camera) return;
        const container = this.canvas.parentElement;
        const w = container.clientWidth || 800;
        const h = container.clientHeight || 560;
        this.camera.aspect = w / h;
        this.camera.updateProjectionMatrix();
        this.renderer.setSize(w, h);
        this.updateAdaptiveLayout();
    }

    // 📐 UNIFORM ADAPTIVE 3D SCALING & AUTO-FRAMING ENGINE
    updateAdaptiveLayout() {
        if (!this.camera) return;
        const aspect = this.camera.aspect || (16 / 9);

        // Responsive Camera FOV, Distance & Mesh Stacking
        if (aspect < 0.70) {
            // 📱 9:16 Vertical Portrait (TikTok / Shorts / Reels)
            this.camera.fov = 68;
            this.baseDist = 23;
            if (this.textMeshGroup) {
                this.textMeshGroup.scale.set(0.72, 0.72, 0.72);
                this.textMeshGroup.position.set(0, 1.8, 0);
            }
        } else if (aspect >= 0.70 && aspect < 0.90) {
            // 📱 4:5 Social Portrait (Instagram / FB)
            this.camera.fov = 64;
            this.baseDist = 20.5;
            if (this.textMeshGroup) {
                this.textMeshGroup.scale.set(0.82, 0.82, 0.82);
                this.textMeshGroup.position.set(0, 0.8, 0);
            }
        } else if (aspect >= 0.90 && aspect < 1.30) {
            // ⏹️ 1:1 Square (Instagram / Discord)
            this.camera.fov = 62;
            this.baseDist = 19;
            if (this.textMeshGroup) {
                this.textMeshGroup.scale.set(0.88, 0.88, 0.88);
                this.textMeshGroup.position.set(0, 0, 0);
            }
        } else if (aspect >= 1.30 && aspect < 2.0) {
            // 🖥️ 16:9 Standard Landscape (YouTube / PC)
            this.camera.fov = 60;
            this.baseDist = 18;
            if (this.textMeshGroup) {
                this.textMeshGroup.scale.set(1.0, 1.0, 1.0);
                this.textMeshGroup.position.set(0, 0, 0);
            }
        } else {
            // 🎬 21:9 UltraWide Cinema
            this.camera.fov = 56;
            this.baseDist = 17;
            if (this.textMeshGroup) {
                this.textMeshGroup.scale.set(1.0, 1.0, 1.0);
                this.textMeshGroup.position.set(0, 0, 0);
            }
        }

        this.camera.updateProjectionMatrix();
        this.updateRobotPosition();
    }
    
