            const hornR = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.12, 2.2, 8), trimMat);
            hornR.position.set(1.0, 1.2, -0.3); hornR.rotation.z = -0.45; hornR.rotation.x = -0.3; headGroup.add(hornR);

