            const arcL = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.3, 0.22, 20), coreMat);
            arcL.rotation.x = Math.PI / 2; arcL.position.set(-0.55, 2.5, 0.68); torsoGroup.add(arcL);
            const arcRingL = new THREE.Mesh(new THREE.TorusGeometry(0.36, 0.05, 12, 24), trimMat);
            arcRingL.position.set(-0.55, 2.5, 0.74); torsoGroup.add(arcRingL);

