            const shinL = new THREE.Mesh(new THREE.CylinderGeometry(0.34, 0.42, 1.4, 12), armorMat); shinL.position.set(0, -2.45, 0); legL.add(shinL);
            const bootL = new THREE.Mesh(new THREE.BoxGeometry(0.85, 0.45, 1.3), trimMat); bootL.position.set(0, -3.25, 0.2); legL.add(bootL);
            robot3LeftLeg = legL; robot3Group.add(legL);

            const legR = new THREE.Group(); legR.position.set(0.9, 0.2, 0);
            const thighR = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.3, 1.4, 12), armorMat); thighR.position.set(0, -0.85, 0); legR.add(thighR);
            const kneeR = new THREE.Mesh(new THREE.SphereGeometry(0.35, 10, 10), jointMat); kneeR.position.set(0, -1.65, 0); legR.add(kneeR);
